/**
 * Boot, orchestration, the frame loop.
 *
 * Order of operations matters here: the page must sit on TRUE black until the
 * fonts, textures and the hero clip are all decodable, otherwise the sequence
 * starts and the figure pops in three frames later. Nothing is revealed until
 * everything needed for the first eight seconds is in hand.
 */

import { Stage } from './gl/stage.js';
import { Clip } from './lib/clip.js';
import { computeLayout } from './scene/layout.js';
import { buildWord, fontsReady } from './scene/type.js';
import { Furniture } from './scene/furniture.js';
import { sample, letterOrder, CUES, T, LetterInfo } from './scene/timeline.js';
import { damp, clamp } from './lib/ease.js';
import { initUniverse, UniverseInstance } from './scene2/boot2.js';
import { initChrono, ChronoInstance } from './scene3/boot3.js';
import { initGallery, GalleryInstance } from './scene4/boot4.js';
import { initFinale, FinaleInstance } from './scene6/boot6.js';
import { initDevCard } from './scene/devcard.js';
import { initSoundUI } from './lib/sound.js';
import { initHUD } from './scene/hud.js';
import { initProjectModal } from './scene/projectModal.js';
import { initDeviceShowcase } from './scene/deviceShowcase.js';
import { initGitHub } from './scene/github.js';
import { initParticles } from './scene/particles.js';
import { initDynamicIsland } from './scene/dynamicIsland.js';
import { initSpatialHUD } from './scene/spatialHUD.js';
import { initUniversalTilt } from './scene/tilt.js';
import { initMagicalReveal } from './scene/magicalReveal.js';
import { initGameLoader } from './scene/gameLoader.js';

// a cinematic page manages its own positions; the browser restoring an old
// scroll offset mid-boot yanks the visitor (and any scripted anchor) around
if ('scrollRestoration' in history) history.scrollRestoration = 'manual';

const MEDIA = 'public/media/';
const MIN_BLACK = 620; // the darkness must be felt, even on a fast line

const root = document.documentElement;
const boot = document.getElementById('boot') as HTMLElement;
const bootFill = document.getElementById('bootFill') as HTMLElement;
const bootEnter = document.getElementById('bootEnter') as HTMLButtonElement;

const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;

interface Clips {
  hero: Clip;
  [key: string]: Clip;
}

interface AppState {
  stage: Stage | null;
  furniture: Furniture | null;
  clips: Clips;
  layout: ReturnType<typeof computeLayout> | null;
  word: ReturnType<typeof buildWord> | null;
  order: number[];
  t0: number;
  fired: Set<string>;
  pointer: { x: number; y: number; tx: number; ty: number };
  running: boolean;
  heroOnScreen?: boolean;
  universe?: UniverseInstance | null;
  chrono?: ChronoInstance | null;
  gallery?: GalleryInstance | null;
  finale?: FinaleInstance | null;
}

const app: AppState = {
  stage: null,
  furniture: null,
  clips: { hero: null as any },
  layout: null,
  word: null,
  order: [],
  t0: 0,
  fired: new Set(),
  pointer: { x: 0, y: 0, tx: 0, ty: 0 },
  running: false,
};

// --------------------------------------------------------------------------

async function main(): Promise<void> {
  initDevCard();
  initSoundUI();
  initHUD();
  initProjectModal();
  initDynamicIsland();
  initSpatialHUD();
  initParticles();
  initUniversalTilt();
  initMagicalReveal();

  const canvas = document.getElementById('stage') as HTMLCanvasElement;
  app.stage = new Stage(canvas);
  app.furniture = new Furniture(document);

  if (!app.stage.ok) return degrade('WebGL unavailable');

  let manifest: { clips: Record<string, any> };
  const vStamp = `?v=${Date.now()}`;
  try {
    manifest = await fetch(`${MEDIA}manifest.json${vStamp}`).then((r) => r.json());
  } catch {
    return degrade('media manifest missing');
  }

  const steps = 3;
  let done = 0;
  const tick = () => {
    done++;
    bootFill.style.width = `${Math.min(100, Math.round((done / steps) * 100))}%`;
  };

  const startedAt = performance.now();

  const mk = (name: string, loopFade: number, loop = false) => {
    const c = manifest.clips[name];
    const src: { url: string; type: string }[] = [];
    if (c.mp4) src.push({ url: `${MEDIA}${c.mp4}${vStamp}`, type: 'video/mp4' });
    if (c.webm) src.push({ url: `${MEDIA}${c.webm}${vStamp}`, type: 'video/webm' });
    return new Clip({
      src,
      poster: `${MEDIA}${c.poster}${vStamp}`,
      w: c.w,
      h: c.h,
      track: c.track,
      loopFade,
      loop,
    });
  };
  app.clips.hero = mk('hero', 0.7, false);

  layout();
  window.addEventListener('resize', debounce(layout, 140));
  window.addEventListener('orientationchange', () => setTimeout(layout, 220));

  // Launch Cinematic Gaming Loading Screen
  const loader = initGameLoader({
    onComplete: async ({ visitorName, skipped }) => {
      try {
        await assetsReady;
        await app.clips.hero.play().catch(() => {});
      } catch (err) {
        console.warn('[lokesh] asset loading issue:', err);
      }
      begin(visitorName);
    }
  });

  const assetsReady = (async () => {
    loader.updateProgress(0.18, 'Decoding Typography & Core Manifest...');
    await fontsReady();
    loader.updateProgress(0.45, 'Fonts Ready. Loading Shaders & Textures...');
    if (!app.stage) return false;
    await app.stage.loadTextures({
      grunge: 'public/tex/grunge.png',
      grain: 'public/tex/grain.png',
    });
    loader.updateProgress(0.72, 'WebGL Stage Ready. Synchronizing Hero Stream...');
    await app.clips.hero.whenReady();
    loader.updateProgress(0.95, 'Hero Cinematic Ready. Finalizing Scene...');
    const held = performance.now() - startedAt;
    if (held < MIN_BLACK) await wait(MIN_BLACK - held);
    loader.setReady();
    return true;
  })();

  // The later scenes build while the hero plays, so scrolling into them is
  // instant; each one runs only while it is actually on screen
  initUniverse().then((u) => { app.universe = u; })
    .catch((e) => console.warn('[lokesh] universe unavailable:', e.message));
  initChrono().then((c) => { app.chrono = c; })
    .catch((e) => console.warn('[lokesh] chrono unavailable:', e.message));
  initGallery().then((g) => { app.gallery = g; })
    .catch((e) => console.warn('[lokesh] gallery unavailable:', e.message));
  initFinale().then((f) => { app.finale = f; })
    .catch((e) => console.warn('[lokesh] finale unavailable:', e.message));
  initDeviceShowcase();
  initGitHub();
}

function begin(visitorName: string): void {
  boot.classList.add('is-done');
  root.classList.remove('is-booting');
  root.classList.add('is-booted');
  app.t0 = performance.now();
  app.running = true;
  bindPointer();

  if (visitorName && visitorName !== 'GUEST OPERATOR') {
    const chip = document.getElementById('chipArtist');
    if (chip) {
      const orig = chip.innerHTML;
      chip.innerHTML = `<span>• OPERATOR: ${visitorName.toUpperCase()} // ACCESS GRANTED •</span>`;
      setTimeout(() => {
        chip.innerHTML = orig;
      }, 8000);
    }
  }

  // ?t=4.2 starts the sequence part-way through, and ?t=end lands on the
  // settled composition. Purely a review aid for tuning a single beat without
  // sitting through the whole opening each time.
  const q = new URLSearchParams(location.search).get('t');
  if (q !== null) {
    const at = q === 'end' ? T.settled : parseFloat(q);
    if (Number.isFinite(at)) {
      app.t0 = performance.now() - at * 1000;
      for (const [when, name] of CUES) {
        if (at >= when) { app.fired.add(name); root.classList.add(`is-${name}`); }
      }
    }
  }
  if (reduced) {
    // honour the preference fully: land on the finished composition and hold it
    // still - no build-up, no looping walk, no drifting grain
    app.t0 = performance.now() - T.settled * 1000;
    for (const [, name] of CUES) root.classList.add(`is-${name}`);
    const c = app.clips.hero;
    const still = () => {
      c.pause();
      renderStill();
      window.addEventListener('resize', debounce(renderStill, 160));
    };
    c.el.addEventListener('seeked', still, { once: true });
    c.el.currentTime = Math.min(6, (c.duration || 8) * 0.6);
    return;
  }
  requestAnimationFrame(frame);
}

/** Autoplay was refused — offer a single deliberate entry point. */
function awaitGesture(): void {
  const bar = document.querySelector('.boot__bar');
  if (bar) (bar as HTMLElement).style.display = 'none';
  bootEnter.hidden = false;
  const unlock = async () => {
    window.removeEventListener('pointerdown', unlock);
    window.removeEventListener('keydown', unlock);
    window.removeEventListener('scroll', unlock);
    await app.clips.hero.play().catch(() => {});
    begin('GUEST OPERATOR');
  };
  window.addEventListener('pointerdown', unlock, { once: true });
  window.addEventListener('keydown', unlock, { once: true });
  window.addEventListener('scroll', unlock, { once: true });
  bootEnter.addEventListener('click', unlock, { once: true });
}

// --------------------------------------------------------------------------

function layout(): void {
  const w = window.innerWidth;
  const h = window.innerHeight;
  const L = computeLayout(w, h);
  app.layout = L;
  if (!app.stage) return;
  app.stage.resize(L);

  const capPx = Math.round(L.word.capH * L.dpr);
  if (!app.word || Math.abs(app.word.capPx - capPx) > 2) {
    const word = buildWord(capPx, app.stage.maxTexture);
    word.capPx = capPx;
    app.word = word;
    app.stage.setWord(word);
    app.order = letterOrder(word.letters as { u0: number; u1: number }[]);
  }
  app.furniture?.apply(L);
}

function bindPointer(): void {
  if (reduced || matchMedia('(pointer: coarse)').matches) return;
  window.addEventListener('pointermove', (e: PointerEvent) => {
    // normalised to -1..1, then damped in the frame loop; the response is
    // deliberately small — depth, not a toy
    app.pointer.tx = (e.clientX / window.innerWidth) * 2 - 1;
    app.pointer.ty = (e.clientY / window.innerHeight) * 2 - 1;

    // Direct screen-space pointer for real-time specular spotlight
    if (app.stage) {
      app.stage.pointerScreen[0] = e.clientX / window.innerWidth;
      app.stage.pointerScreen[1] = e.clientY / window.innerHeight;
      app.stage.pointerActive = 1.0;
    }
  }, { passive: true });

  window.addEventListener('pointerleave', () => {
    app.pointer.tx = 0;
    app.pointer.ty = 0;
    if (app.stage) app.stage.pointerActive = 0.0;
  });

  // Stage click shockwave ripple
  window.addEventListener('pointerdown', (e: PointerEvent) => {
    if (e.target instanceof Element && e.target.closest('button, a, input, select, textarea, .dev-modal, .proj-modal, .dynamic-island, .spatial-hud')) return;
    if (app.stage) {
      app.stage.shockwave = 0.02;
      app.stage.shockwavePos = [e.clientX / window.innerWidth, e.clientY / window.innerHeight];
    }
  });
}

let last = 0;
function frame(now: number): void {
  if (!app.running || !app.stage) return;
  const t = (now - app.t0) / 1000;
  const dt = Math.min(0.05, (now - last) / 1000 || 0.016);
  last = now;

  for (const [at, name] of CUES) {
    if (t >= at && !app.fired.has(name)) {
      app.fired.add(name);
      root.classList.add(`is-${name}`);
    }
  }

  const p = app.pointer;
  p.x = damp(p.x, p.tx, 3.1, dt);
  p.y = damp(p.y, p.ty, 3.1, dt);
  // parallax only comes alive once the composition has settled
  const gate = clamp((t - T.settled + 0.9) / 1.2);
  app.stage.parallax.x = p.x * gate;
  app.stage.parallax.y = p.y * gate;

  // Progress shockwave ripple
  if (app.stage.shockwave > 0) {
    app.stage.shockwave += dt * 1.6;
    if (app.stage.shockwave >= 1.0) app.stage.shockwave = 0;
  }

  const state = sample(t, app.word!.letters.length, app.order);

  // after the intro the wordmark breathes very slightly, so the frame never
  // becomes a static image
  if (state.settled) {
    const b = Math.sin(t * 0.42) * 0.5 + Math.sin(t * 0.27 + 1.3) * 0.5;
    for (const l of state.letters) l.dy = b * 0.0035;
  }

  app.stage.render(state, t, app.clips);
  requestAnimationFrame(frame);
}

// --------------------------------------------------------------------------

function degrade(reason: string): void {
  console.warn('[lokesh] falling back:', reason);
  root.classList.remove('is-booting');
  root.classList.add('is-fallback');
  boot.classList.add('is-done');
  for (const [, name] of CUES) root.classList.add(`is-${name}`);
  const stageWrap = document.querySelector('.stage-wrap');
  if (stageWrap) {
    stageWrap.insertAdjacentHTML('afterbegin',
      '<div class="fallback"><p>LOKESH</p>'
      + '<small>Welcome to my world</small></div>');
  }
}

function renderStill(): void {
  layout();
  if (!app.stage) return;
  const state = sample(T.settled + 1, app.word!.letters.length, app.order);
  app.stage.render(state, T.settled + 1, app.clips);
}

function wait(ms: number): Promise<void> {
  return new Promise((r) => setTimeout(r, ms));
}

function debounce<T extends (...args: any[]) => any>(fn: T, ms: number): T {
  let id: ReturnType<typeof setTimeout>;
  return ((...a: Parameters<T>) => { clearTimeout(id); id = setTimeout(() => fn(...a), ms); }) as T;
}

// mobile menu
const burger = document.getElementById('burger') as HTMLButtonElement;
const menu = document.getElementById('menu') as HTMLElement;
menu?.querySelectorAll('a').forEach((a, i) => a.style.setProperty('--i', String(i)));
function setMenu(open: boolean): void {
  burger.setAttribute('aria-expanded', String(open));
  root.classList.toggle('is-menu', open);
  if (open) menu.hidden = false;
  else setTimeout(() => { if (!root.classList.contains('is-menu')) menu.hidden = true; }, 500);
}
burger?.addEventListener('click', () =>
  setMenu(burger.getAttribute('aria-expanded') !== 'true'));
menu?.addEventListener('click', (e: MouseEvent) => {
  if ((e.target as Element).closest('a')) setMenu(false);
});
window.addEventListener('keydown', (e: KeyboardEvent) => {
  if (e.key === 'Escape' && root.classList.contains('is-menu')) setMenu(false);
});

// Smooth in-page anchor navigation
document.addEventListener('click', (e: MouseEvent) => {
  const a = (e.target as Element).closest('a[data-nav]') as HTMLAnchorElement | null;
  if (!a) return;
  const href = a.getAttribute('href');
  if (href === '#') {
    e.preventDefault();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  } else if (href && href.startsWith('#')) {
    const target = document.querySelector(href);
    if (target) {
      e.preventDefault();
      target.scrollIntoView({ behavior: 'smooth' });
    }
  }
});

const heroScrollBtn = document.getElementById('heroScroll') as HTMLButtonElement;
if (heroScrollBtn) {
  heroScrollBtn.addEventListener('click', () => {
    const target = document.getElementById('universe');
    if (target) target.scrollIntoView({ behavior: 'smooth' });
  });
  window.addEventListener('scroll', () => {
    heroScrollBtn.classList.toggle('is-hidden', window.scrollY > 60);
  }, { passive: true });
}

// The hero is position:fixed behind the flow, so once scene two covers it there
// is nothing to see - stop decoding its video rather than burning battery on
// frames nobody is looking at.
const heroWrap = document.querySelector('.stage-wrap') as HTMLElement | null;
if (heroWrap && 'IntersectionObserver' in window) {
  const spacer = document.querySelector('.hero-spacer');
  if (spacer) {
    new IntersectionObserver(([e]) => {
      const c = app.clips.hero;
      if (!c) return;
      app.heroOnScreen = e.isIntersecting;
      if (e.isIntersecting) { c.play(); heroWrap.style.visibility = ''; }
      else { c.pause(); heroWrap.style.visibility = 'hidden'; }
    }, { threshold: 0 }).observe(spacer);
  }
}

// Scene 03 Technical Skills Matrix entrance animation
const skillsSec = document.getElementById('skills');
if (skillsSec && 'IntersectionObserver' in window) {
  const skCards = skillsSec.querySelectorAll('.sk-card');
  const skObserver = new IntersectionObserver((entries) => {
    for (const e of entries) {
      if (e.isIntersecting) {
        skillsSec.classList.add('is-visible');
        skCards.forEach((c, idx) => {
          setTimeout(() => c.classList.add('is-revealed'), idx * 100);
        });
        skObserver.unobserve(skillsSec);
      }
    }
  }, { threshold: 0.15 });
  skObserver.observe(skillsSec);
}

// pause the decoder when the tab is hidden rather than burning battery
// decoding frames nobody is looking at
document.addEventListener('visibilitychange', () => {
  const hidden = document.visibilityState === 'hidden';
  for (const c of Object.values(app.clips)) {
    if (!c) continue;
    if (hidden) c.pause();
    else if (app.heroOnScreen !== false) c.play();
  }
});

// Review hook. Draws one frame on demand and reads the framebuffer in the SAME
// task, because the context is created without preserveDrawingBuffer. Rendering
// here rather than piggy-backing on the animation loop means it still works when
// the tab is hidden and rAF is throttled to a stop.
(window as any).__shot = async (name = 'shot', at: number | null = null) => {
  if (!app.word) return 'not ready';
  const t = at !== null ? at : (performance.now() - app.t0) / 1000;
  app.stage!.render(sample(t, app.word.letters.length, app.order), t, app.clips);
  const url = app.stage!.canvas.toDataURL('image/png');
  await fetch(`/__shot?name=${encodeURIComponent(name)}`,
    { method: 'POST', body: url });
  return `${app.stage!.canvas.width}x${app.stage!.canvas.height} @ t=${t.toFixed(2)}`;
};

// live tuning of the letter surface while matching the reference art
(window as any).__tune = (k: string, v: number) => { (app.stage as any)[k] = v; return (app.stage as any)[k]; };

main().catch((e) => degrade(e.message));